fragment.trace:
JWT token details
<metadata name="AccessTokenIssuer" value='@{
    var token = context.Variables["jwt-token"] as Jwt;
    return !string.IsNullOrWhiteSpace(token?.Issuer) ? token.Issuer : "";
}' />
<metadata name="AccessTokenSubject" value='@{
    var token = context.Variables["jwt-token"] as Jwt;
    return !string.IsNullOrWhiteSpace(token?.Subject) ? token.Subject  : "";
}' />
<metadata name="AccessTokenClientId" value='@{
    var token = context.Variables["jwt-token"] as Jwt;
    var clientId = token?.Claims.GetValueOrDefault("azp");
    return !string.IsNullOrWhiteSpace(clientId) ? clientId : "";
}' />
